//! Runtime primitives of the **Sayagi Rust** PWA metaframework.
//!
//! This crate is compiled twice: once for the Axum server (`ssr`) and once for the
//! Wasm client that hydrates it (`hydrate`). It provides the pieces an app would
//! otherwise hand-roll for every project:
//!
//! * [`MobileLayout`], [`HeaderBar`], [`BottomNav`], [`LinkButton`] and [`PullToRefresh`] — the mobile UI shell.
//! * [`param`] — typed access to `[id]`-style route parameters.
//! * [`register_service_worker`] and [`watch_connectivity`] — PWA wiring.
//! * [`RouteInfo`] — the route table generated by `sayagi-build`.

mod components;
mod params;
mod pwa;

pub use components::{
    BottomNav, HeaderBar, LinkButton, MobileLayout, NavItem, PullToRefresh, default_nav_items,
    icon_svg,
};
pub use params::{param, param_or};
pub use pwa::{register_service_worker, watch_connectivity};

/// The flavour of a generated route.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RouteKind {
    /// Only literal segments, e.g. `/dashboard`.
    Static,
    /// Contains at least one `[param]` segment, e.g. `/containers/:id`.
    Dynamic,
    /// Ends with a `[...rest]` catch-all, e.g. `/files/*path`.
    Wildcard,
}

impl RouteKind {
    /// Lowercase label, useful for debugging UIs.
    pub fn label(self) -> &'static str {
        match self {
            RouteKind::Static => "static",
            RouteKind::Dynamic => "dynamic",
            RouteKind::Wildcard => "wildcard",
        }
    }
}

/// Metadata for one route discovered under `src/pages` at build time.
///
/// The table itself is generated into `ROUTES` by `sayagi-build`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RouteInfo {
    /// leptos_router path pattern, e.g. `/containers/:id`.
    pub path: &'static str,
    /// Source file relative to the app root.
    pub file: &'static str,
    /// Generated module name.
    pub module: &'static str,
    /// Static, dynamic or wildcard.
    pub kind: RouteKind,
}

impl RouteInfo {
    /// Lowercase flavour label.
    pub fn label(&self) -> &'static str {
        self.kind.label()
    }
}

/// Everything an app page needs, in one import.
///
/// ```ignore
/// use sayagi::prelude::*;
///
/// #[component]
/// pub fn Page() -> impl IntoView {
///     let id = param("id");
///     view! { <MobileLayout title="Detail"><p>{id}</p></MobileLayout> }
/// }
/// ```
pub mod prelude {
    pub use crate::components::{
        BottomNav, HeaderBar, LinkButton, MobileLayout, NavItem, PullToRefresh, default_nav_items,
        icon_svg,
    };
    pub use crate::params::{param, param_or};
    pub use crate::pwa::{register_service_worker, watch_connectivity};
    pub use crate::{RouteInfo, RouteKind};
}
